#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class ProgramLifecycleReturns(Func<RuntimeEntries.CoreDrawPhaseObligationsEntries> getCoreDrawPhaseObligationsRuntime, Func<ProgramPipelineHooks> getProgramPipelineHooks, Func<RuntimeEntries.CoreGameEngineNativeDrawAttemptsEntries> getCoreGameEngineNativeDrawAttemptsRuntime, Func<RuntimeEntries.CoreGameEngineRoundEndingEntries> getCoreGameEngineRoundEndingRuntime, Func<RuntimeEntries.CharacterYanPuOlEntries> getCharacterYanPuOlRuntime, Func<RuntimeEntries.CoreActualTurnsEntries> getCoreActualTurnsRuntime, EngineStates.CoreMatchParticipantsState matchParticipantsState, Func<RuntimeEntries.CoreGameEngineDyingEntryProgramsEntries> getCoreGameEngineDyingEntryProgramsRuntime, Func<RuntimeEntries.CharacterZhouQunOlEntries> getCharacterZhouQunOlRuntime, Func<RuntimeEntries.CharacterDuFuRenOlEntries> getCharacterDuFuRenOlRuntime, Func<RuntimeEntries.CharacterChengGongYingOlEntries> getCharacterChengGongYingOlRuntime, Func<RuntimeEntries.CoreGameEngineProgramLifecycleEntries> getCoreGameEngineProgramLifecycleRuntime, Func<RuntimeEntries.CoreGameEngineIdentityConcealmentEntries> getCoreGameEngineIdentityConcealmentRuntime, Func<RuntimeEntries.CharacterBeiMiHuOlEntries> getCharacterBeiMiHuOlRuntime, Func<RuntimeEntries.CoreAlternativePhaseCostProgramsEntries> getCoreAlternativePhaseCostProgramsRuntime, Func<RuntimeEntries.CoreGameEngineCharacterStateProgramsEntries> getCoreGameEngineCharacterStateProgramsRuntime, EngineStates.CoreDelayedTurnEffectsState delayedTurnEffectsState, Func<RuntimeEntries.CoreActualDiscardPhaseEntries> getCoreActualDiscardPhaseRuntime) : IProgramLifecycleReturns
{
    public void DrawPhaseObligation(ProgramLifecycleTriggerWindowFrame frame) => getCoreDrawPhaseObligationsRuntime().ReturnDrawPhaseObligationWindow(frame);
    public bool PipelineCompleted(ProgramLifecycleTriggerWindowFrame frame) => getProgramPipelineHooks().LifecycleWindowCompleted(frame);
    public void NativeDrawAttempt(ProgramLifecycleTriggerWindowFrame frame) => getCoreGameEngineNativeDrawAttemptsRuntime().ReturnNativeDrawAttemptWindow(frame);
    public void RoundEnding(ProgramLifecycleTriggerWindowFrame frame) => getCoreGameEngineRoundEndingRuntime().ReturnRoundEndingLifecycle(frame);
