    public void DrawPhase(ProgramLifecycleTriggerWindowFrame frame, bool actualPhaseSubstituted) => getCoreActualTurnsRuntime().CompleteDrawPhaseAfterProgramWindow(matchParticipantsState.ReferenceToPlayers[frame.OwnerSeat], frame.SkipPlayPhaseAfterDraw, frame.NormalDrawReplaced, frame.NormalDrawAdjustment, frame.FrozenBaseDrawCount, actualPhaseSubstituted);
    public void PlayPhase() => getCoreGameEngineProgramLifecycleRuntime().CompletePlayPhaseAfterProgramWindow();
    public void EndTurn() => getCoreActualTurnsRuntime().EndTurn();
    public void JudgmentStarting(ProgramLifecycleTriggerWindowFrame frame) => getCoreAlternativePhaseCostProgramsRuntime().CompleteActualJudgmentStarting(frame);
    public void CharacterStateChange(ProgramLifecycleTriggerWindowFrame frame) => getCoreGameEngineCharacterStateProgramsRuntime().ResumeCharacterStateChange(frame);
    public void DrawPhaseEnded(int seat, int delayedEffects) => getCoreActualTurnsRuntime().CompleteTurnStartAfterDraw(matchParticipantsState.ReferenceToPlayers[seat], (GameEngine.DelayedTurnEffects)delayedEffects, drawPhaseEndedProgramsCompleted: true);
    public void AfterNormalDraw(int seat) => getCoreActualTurnsRuntime().CompleteTurnStartAfterDraw(matchParticipantsState.ReferenceToPlayers[seat], delayedTurnEffectsState.ReferenceToPendingTurnDelayedEffects, afterNormalDrawProgramsCompleted: true, drawPhaseEndedProgramsCompleted: true);
    public void DiscardPhase(int seat) => getCoreActualDiscardPhaseRuntime().CompleteDiscardPhaseAfterProgramWindow(matchParticipantsState.ReferenceToPlayers[seat]);
}
